insert into public.users (name, email, bio, "current_role", location, linkedin_url, contact_preference, contact_handle, role) values
  ('Ananya Rao', 'ananya.rao@cohort.edu', 'Ex-investment banking analyst moving toward growth-stage investing. Happy to walk anyone through a three-statement model or a live deal timeline.', 'MBA Candidate • ex-Investment Banking', 'Mumbai', 'https://linkedin.com/in/ananyarao', 'Email', 'ananya.rao@cohort.edu', 'admin'),
  ('Rahul Menon', 'rahul.menon@cohort.edu', 'Product manager who shipped payments features to 4M users. I like breaking down ambiguous problems and I run mock PM interviews most weekends.', 'MBA Candidate • ex-Product Manager', 'Bangalore', 'https://linkedin.com/in/rahulmenon', 'WhatsApp', '+91 98450 11223', 'student'),
  ('Sneha Kulkarni', 'sneha.kulkarni@cohort.edu', 'Three years at a strategy consulting firm across FMCG and retail clients. Cracked 20+ cases; happy to run practice cases for anyone recruiting.', 'MBA Candidate • ex-Strategy Consultant', 'Delhi NCR', 'https://linkedin.com/in/snehakulkarni', 'Email', 'sneha.kulkarni@cohort.edu', 'student'),
  ('Arjun Sethi', 'arjun.sethi@cohort.edu', 'Backend engineer turned ML practitioner. Built recommendation systems at scale. Will happily pair-program Python or debug your notebook.', 'MBA Candidate • ex-Software Engineer', 'Hyderabad', 'https://linkedin.com/in/arjunsethi', 'Email', 'arjun.sethi@cohort.edu', 'student'),
  ('Meera Iyer', 'meera.iyer@cohort.edu', 'Brand manager across two FMCG launches. I know the India go-to-market playbook well and can review positioning or pricing decks.', 'MBA Candidate • ex-Brand Manager', 'Mumbai', 'https://linkedin.com/in/meeraiyer', 'LinkedIn', 'https://linkedin.com/in/meeraiyer', 'student'),
  ('Kabir Shah', 'kabir.shah@cohort.edu', 'Worked on two private equity deals in healthcare services. Deep on diligence packs, LBO mechanics and PE interview loops.', 'MBA Candidate • ex-Private Equity Associate', 'Delhi NCR', 'https://linkedin.com/in/kabirshah', 'Email', 'kabir.shah@cohort.edu', 'student'),
  ('Divya Nair', 'divya.nair@cohort.edu', 'Supply chain lead for a manufacturing plant with 400 people. I enjoy operations problems and can help with plant-level analytics.', 'MBA Candidate • ex-Operations Manager', 'Chennai', 'https://linkedin.com/in/divyanair', 'WhatsApp', '+91 99400 55667', 'student'),
  ('Zoya Khan', 'zoya.khan@cohort.edu', 'Founded a D2C skincare brand and ran it for two years. Raised a small angel round; happy to talk fundraising, unit economics and burnout.', 'MBA Candidate • Founder', 'Bangalore', 'https://linkedin.com/in/zoyakhan', 'WhatsApp', '+91 98860 33445', 'student'),
  ('Vikram Desai', 'vikram.desai@cohort.edu', 'Equity research on the consumer sector, then a stint at a crypto exchange. I read a lot and I keep a shared library of research notes.', 'MBA Candidate • ex-Equity Research', 'Mumbai', 'https://linkedin.com/in/vikramdesai', 'Email', 'vikram.desai@cohort.edu', 'student'),
  ('Priya Bansal', 'priya.bansal@cohort.edu', 'Healthcare consultant with a clinical background. Comfortable translating between doctors and business teams; strong on market sizing.', 'MBA Candidate • ex-Healthcare Consultant', 'Pune', 'https://linkedin.com/in/priyabansal', 'Email', 'priya.bansal@cohort.edu', 'student'),
  ('Aditya Verma', 'aditya.verma@cohort.edu', 'Media and content strategy, mostly on the monetisation side. I can help with pitch decks, storytelling and anything design-adjacent.', 'MBA Candidate • ex-Content Strategist', 'Delhi NCR', 'https://linkedin.com/in/adityaverma', 'LinkedIn', 'https://linkedin.com/in/adityaverma', 'student'),
  ('Ishaan Gupta', 'ishaan.gupta@cohort.edu', 'Two years in venture capital covering seed-stage SaaS. Screened 300+ startups; can review your deck or make warm intros in the ecosystem.', 'MBA Candidate • ex-VC Analyst', 'Bangalore', 'https://linkedin.com/in/ishaangupta', 'Email', 'ishaan.gupta@cohort.edu', 'student'),
  ('Nikhil Joshi', 'nikhil.joshi@cohort.edu', 'Four years in energy infrastructure project finance. I can sanity-check any model with debt in it, and I know the PPP/regulatory side well.', 'MBA Candidate • ex-Project Finance', 'Ahmedabad', 'https://linkedin.com/in/nikhiljoshi', 'Email', 'nikhil.joshi@cohort.edu', 'student'),
  ('Tara Menon', 'tara.menon@cohort.edu', 'Ran category and pricing for a large online retailer. Very comfortable with SQL, elasticity work and anything that starts with ''why did GMV drop''.', 'MBA Candidate • ex-Category Manager', 'Bangalore', 'https://linkedin.com/in/tarameon', 'WhatsApp', '+91 98800 22114', 'student'),
  ('Rohan Malhotra', 'rohan.malhotra@cohort.edu', 'Corporate lawyer turned generalist. Deal documentation, term sheets and compliance — I can translate anything a lawyer sends you into plain English.', 'MBA Candidate • ex-Corporate Lawyer', 'Delhi NCR', 'https://linkedin.com/in/rohanmalhotra', 'Email', 'rohan.malhotra@cohort.edu', 'student'),
  ('Aisha Siddiqui', 'aisha.siddiqui@cohort.edu', 'Clinical research to health-tech product. I care about how care actually gets delivered, and I''m the person to ask about regulated-industry product work.', 'MBA Candidate • ex-Health-Tech PM', 'Hyderabad', 'https://linkedin.com/in/aishasiddiqui', 'LinkedIn', 'https://linkedin.com/in/aishasiddiqui', 'student'),
  ('Karthik Reddy', 'karthik.reddy@cohort.edu', 'Quant developer at a systematic fund, then a year building trading infra at a crypto exchange. Python, statistics, and healthy scepticism about backtests.', 'MBA Candidate • ex-Quant Developer', 'Chennai', 'https://linkedin.com/in/karthikreddy', 'Email', 'karthik.reddy@cohort.edu', 'student'),
  ('Neha Agarwal', 'neha.agarwal@cohort.edu', 'Campus placement committee this year and ex-HR business partner. If you want a mock interview or a blunt read on your CV, ask me.', 'MBA Candidate • ex-HR Business Partner', 'Mumbai', 'https://linkedin.com/in/nehaagarwal', 'WhatsApp', '+91 99300 77881', 'admin');
