  ('Damodaran Online — the full valuation course', 'Aswath Damodaran''s entire NYU Stern valuation class: slides, lecture videos, spreadsheets and the industry datasets he updates every January. If you only bookmark one finance site, this is it.', 'Academics', 'https://pages.stern.nyu.edu/~adamodar/', ARRAY['valuation', 'corporate finance', 'NYU Stern']::text[], (select id from public.users where email = 'ananya.rao@cohort.edu'), '2026-07-15T00:00:00.000Z'),
  ('Damodaran''s updated industry datasets', 'Betas, cost of capital, margins and multiples by sector and geography — the numbers you cite when a professor asks where your WACC came from.', 'Finance', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/data.html', ARRAY['data', 'WACC', 'valuation']::text[], (select id from public.users where email = 'vikram.desai@cohort.edu'), '2026-07-17T00:00:00.000Z'),
  ('MIT OCW — Finance Theory I (15.401)', 'Full lecture notes and problem sets covering NPV, portfolio theory, CAPM and capital structure. Maps almost one-to-one onto our Term 1 corporate finance syllabus.', 'Academics', 'https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/', ARRAY['academics', 'corporate finance', 'MIT']::text[], (select id from public.users where email = 'kabir.shah@cohort.edu'), '2026-07-18T00:00:00.000Z'),
  ('MIT OCW — Marketing Management (15.810)', 'Segmentation, positioning, pricing and channel strategy with the case list. Good companion reading before marketing management sessions.', 'Marketing', 'https://ocw.mit.edu/courses/15-810-marketing-management-fall-2015/', ARRAY['academics', 'marketing', 'MIT']::text[], (select id from public.users where email = 'meera.iyer@cohort.edu'), '2026-07-19T00:00:00.000Z'),
  ('MIT OCW — full management course catalogue', 'Every Sloan course MIT has published: operations, system dynamics, organisational processes, entrepreneurship. Free lecture notes for anything you are behind on.', 'Academics', 'https://ocw.mit.edu/search/?d=Sloan%20School%20of%20Management', ARRAY['academics', 'operations', 'MIT']::text[], (select id from public.users where email = 'divya.nair@cohort.edu'), '2026-07-20T00:00:00.000Z'),
  ('NPTEL — management course library', 'IIT/IISc video courses in management, operations research and economics. Useful when you want the same topic explained a second way, in an Indian context.', 'Academics', 'https://nptel.ac.in/course.html', ARRAY['academics', 'India', 'lectures']::text[], (select id from public.users where email = 'priya.bansal@cohort.edu'), '2026-07-21T00:00:00.000Z'),
  ('Term 1 Corporate Finance — consolidated cohort notes', 'Chapter-wise notes with solved past-paper questions: capital structure, WACC, dividend policy, and the formula sheet the seniors circulated.', 'Academics', 'https://drive.google.com/drive/folders/cohort-first-corpfin', ARRAY['academics', 'finance', 'notes']::text[], (select id from public.users where email = 'vikram.desai@cohort.edu'), '2026-08-17T00:00:00.000Z'),
  ('Statistics & econometrics refresher — Khan Academy', 'If regression output still feels like magic, this is the fastest way to fix it before the quant methods midterm.', 'Analytics', 'https://www.khanacademy.org/math/statistics-probability', ARRAY['statistics', 'regression', 'basics']::text[], (select id from public.users where email = 'arjun.sethi@cohort.edu'), '2026-07-23T00:00:00.000Z'),
