  ('Levels.fyi — compensation data', 'Real, verified pay bands by company, level and city. Use it before you negotiate anything.', 'Career', 'https://www.levels.fyi/', ARRAY['compensation', 'negotiation', 'careers']::text[], (select id from public.users where email = 'rahul.menon@cohort.edu'), '2026-08-21T00:00:00.000Z'),
  ('Ask a Manager', 'Twenty years of workplace questions answered well. Unreasonably useful for internships and first-job politics.', 'Career', 'https://www.askamanager.org/', ARRAY['workplace', 'careers', 'advice']::text[], (select id from public.users where email = 'aditya.verma@cohort.edu'), '2026-08-21T00:00:00.000Z'),
  ('Finshots — three-minute business news', 'Daily Indian business explainers. The cheapest way to sound informed in a networking call.', 'Career', 'https://finshots.in/', ARRAY['India', 'news', 'business']::text[], (select id from public.users where email = 'vikram.desai@cohort.edu'), '2026-08-22T00:00:00.000Z'),
  ('The Ken', 'Long-form Indian business journalism. One story a day, properly reported — good for industry prep on Indian firms.', 'Career', 'https://the-ken.com/', ARRAY['India', 'journalism', 'industry']::text[], (select id from public.users where email = 'vikram.desai@cohort.edu'), '2026-08-22T00:00:00.000Z'),
  ('Inc42 — Indian startup ecosystem', 'Funding news, sector reports and the DataLabs research on Indian startups.', 'Career', 'https://inc42.com/', ARRAY['India', 'startups', 'funding']::text[], (select id from public.users where email = 'zoya.khan@cohort.edu'), '2026-08-22T00:00:00.000Z'),
  ('CV and cover letter clinic — cohort templates', 'Two CV templates (finance and consulting), the bullet formula that survived MBB screening, and ten before/after rewrites.', 'Career', 'https://drive.google.com/drive/folders/cohort-first-cv-clinic', ARRAY['CV', 'career', 'templates']::text[], (select id from public.users where email = 'priya.bansal@cohort.edu'), '2026-08-23T00:00:00.000Z'),
  ('Free courses worth actually finishing', 'A curated shortlist — SQL, statistics, negotiation and design — with hours required and what each is genuinely good for.', 'Courses', 'https://drive.google.com/drive/folders/cohort-first-course-shortlist', ARRAY['courses', 'learning', 'career']::text[], (select id from public.users where email = 'aditya.verma@cohort.edu'), '2026-08-20T00:00:00.000Z'),
  ('Wharton Business Foundations (Coursera)', 'Wharton''s core MBA sequence — accounting, marketing, operations, finance — auditable free. Good for filling a weak core.', 'Courses', 'https://www.coursera.org/specializations/wharton-business-foundations', ARRAY['courses', 'core', 'Wharton']::text[], (select id from public.users where email = 'priya.bansal@cohort.edu'), '2026-08-19T00:00:00.000Z'),
  ('The Personal MBA — reading list', 'Josh Kaufman''s list of the business books that are actually worth the hours, ranked and summarised.', 'Books', 'https://personalmba.com/best-business-books/', ARRAY['books', 'reading list']::text[], (select id from public.users where email = 'aditya.verma@cohort.edu'), '2026-08-23T00:00:00.000Z'),
  ('Thinking, Fast and Slow', 'Kahneman on judgement under uncertainty. Shows up in behavioural finance, marketing and negotiation alike.', 'Books', 'https://www.goodreads.com/book/show/11468377-thinking-fast-and-slow', ARRAY['books', 'behavioural', 'decisions']::text[], (select id from public.users where email = 'priya.bansal@cohort.edu'), '2026-08-23T00:00:00.000Z'),
  ('The Goal — Goldratt', 'A novel about a factory that teaches the theory of constraints better than any ops textbook. Read it before the operations core.', 'Books', 'https://www.goodreads.com/book/show/113934.The_Goal', ARRAY['books', 'operations', 'constraints']::text[], (select id from public.users where email = 'divya.nair@cohort.edu'), '2026-08-24T00:00:00.000Z'),
  ('Competitive Strategy — Porter', 'The source text behind half our strategy syllabus. Skim the first four chapters and you''ll follow every session.', 'Books', 'https://www.goodreads.com/book/show/40646.Competitive_Strategy', ARRAY['books', 'strategy', 'Porter']::text[], (select id from public.users where email = 'sneha.kulkarni@cohort.edu'), '2026-08-24T00:00:00.000Z'),
  ('Zero to One — Thiel', 'Contrarian, arguable and short. Useful as a foil in any entrepreneurship discussion.', 'Books', 'https://www.goodreads.com/book/show/18050143-zero-to-one', ARRAY['books', 'startups', 'strategy']::text[], (select id from public.users where email = 'zoya.khan@cohort.edu'), '2026-08-24T00:00:00.000Z');
insert into public.opportunities (title, company, type, industry, role, location, deadline, description, url, posted_by, status, created_at) values
  ('Product Manager — Fintech Startup', 'Setu', 'Job', 'Technology', 'Product', 'Bangalore', '2026-09-15', 'Series B fintech hiring a PM for their lending stack. My ex-manager runs the team — I can refer directly if your profile fits.', 'mailto:rahul.menon@cohort.edu', (select id from public.users where email = 'rahul.menon@cohort.edu'), 'open', '2026-08-16T00:00:00.000Z'),
  ('Summer Internship — Private Equity (Healthcare)', 'ChrysCapital', 'Internship', 'Finance', 'Investment', 'Delhi NCR', '2026-09-05', 'Two summer intern slots open on the healthcare vertical. Modelling test then two rounds. Referrals are read first.', 'mailto:kabir.shah@cohort.edu', (select id from public.users where email = 'kabir.shah@cohort.edu'), 'open', '2026-08-18T00:00:00.000Z'),
  ('Referral — Associate Consultant, Bain', 'Bain & Company', 'Referral', 'Consulting', 'Strategy', 'Mumbai', '2026-09-20', 'I can put in referrals for the lateral hiring window. Send me your CV and a two-line note on why consulting.', 'mailto:sneha.kulkarni@cohort.edu', (select id from public.users where email = 'sneha.kulkarni@cohort.edu'), 'open', '2026-08-19T00:00:00.000Z'),
  ('Looking for a technical co-founder — B2B AI tooling', 'Stealth', 'Startup', 'Technology', 'Engineering', 'Bangalore', NULL, 'Working on document workflows for mid-market finance teams. Two design partners lined up. Want someone who can build the first version.', 'mailto:zoya.khan@cohort.edu', (select id from public.users where email = 'zoya.khan@cohort.edu'), 'open', '2026-08-21T00:00:00.000Z'),
  ('National Case Competition — ₹3L prize pool', 'Unilever Ideatrophy', 'Competition', 'FMCG', 'Strategy', 'Remote', '2026-09-02', 'Teams of three. Brand strategy brief, two-round format, winners get PPI interviews. I''m forming a team — DM if interested.', 'mailto:meera.iyer@cohort.edu', (select id from public.users where email = 'meera.iyer@cohort.edu'), 'open', '2026-08-23T00:00:00.000Z'),
  ('Data Analytics Project — 6 weeks, paid', 'Delhivery', 'Project', 'Logistics', 'Data', 'Remote', '2026-09-10', 'Short paid project building a route-efficiency dashboard. SQL plus one BI tool is enough. Good line on a CV for anyone switching to data.', 'mailto:divya.nair@cohort.edu', (select id from public.users where email = 'divya.nair@cohort.edu'), 'open', '2026-08-24T00:00:00.000Z'),
  ('Equity Research Associate — Consumer Coverage', 'Motilal Oswal', 'Job', 'Finance', 'Research', 'Mumbai', '2026-09-18', 'My old desk is hiring one associate on consumer coverage. Modelling test plus a stock pitch. Send me a one-page pitch and I''ll pass it on.', 'mailto:vikram.desai@cohort.edu', (select id from public.users where email = 'vikram.desai@cohort.edu'), 'open', '2026-08-20T00:00:00.000Z'),
  ('Growth Marketing Intern — D2C Skincare', 'Glowkind', 'Internship', 'Retail', 'Marketing', 'Remote', '2026-09-08', 'Eight weeks, part-time, paid. You''d own performance campaigns and the retention email flow end to end. Good if you want a real growth line on your CV.', 'mailto:zoya.khan@cohort.edu', (select id from public.users where email = 'zoya.khan@cohort.edu'), 'open', '2026-08-22T00:00:00.000Z'),
  ('Alumni fireside — breaking into Product without a tech background', 'Cohort events', 'Event', 'Technology', 'Product', 'Bangalore', '2026-09-04', 'Two alumni PMs from Swiggy and Cred, 45 minutes plus open Q&A. Hybrid — link goes out to whoever registers.', 'mailto:rahul.menon@cohort.edu', (select id from public.users where email = 'rahul.menon@cohort.edu'), 'open', '2026-08-23T00:00:00.000Z'),
  ('Referral — Analyst, Health-Tech Strategy', 'Practo', 'Referral', 'Healthcare', 'Strategy', 'Bangalore', '2026-09-25', 'Strategy team is opening two analyst roles. I still know the hiring manager — happy to refer anyone with a healthcare or analytics angle.', 'mailto:aisha.siddiqui@cohort.edu', (select id from public.users where email = 'aisha.siddiqui@cohort.edu'), 'open', '2026-08-25T00:00:00.000Z');
insert into public.help_requests (title, description, tags, posted_by, status, created_at) values
  ('Looking for someone who has worked on M&A deals', 'I have a PE interview in two weeks with a live-deal case. Would love 30 minutes with anyone who has been on a sell-side process.', ARRAY['M&A', 'private equity', 'interviews']::text[], (select id from public.users where email = 'vikram.desai@cohort.edu'), 'open', '2026-08-20T00:00:00.000Z'),
  ('Can someone review my consulting CV?', 'Switching from operations to consulting. My bullets read like a job description rather than impact. Any MBB eyes welcome.', ARRAY['CV review', 'consulting', 'career']::text[], (select id from public.users where email = 'divya.nair@cohort.edu'), 'open', '2026-08-22T00:00:00.000Z'),
  ('Does anyone know someone at Google (India)?', 'Applying to the APM programme. Looking for a referral or even just someone who has been through the loop recently.', ARRAY['referral', 'product', 'big tech']::text[], (select id from public.users where email = 'aditya.verma@cohort.edu'), 'open', '2026-08-23T00:00:00.000Z'),
  ('Need a teammate for a fintech case competition', 'Two of us signed up, need a third with finance depth. Submission is a 10-slide deck plus a model. Roughly 15 hours of work.', ARRAY['case competition', 'fintech', 'teammate']::text[], (select id from public.users where email = 'priya.bansal@cohort.edu'), 'open', '2026-08-24T00:00:00.000Z'),
  ('Anyone good at Python who can unblock me?', 'Trying to scrape and clean a dataset for my term paper and my merge keeps producing duplicates. Should take someone 20 minutes.', ARRAY['Python', 'data', 'academics']::text[], (select id from public.users where email = 'meera.iyer@cohort.edu'), 'resolved', '2026-08-14T00:00:00.000Z'),
  ('Looking to speak with anyone in Crypto/Web3', 'Curious about the space beyond trading — infrastructure, compliance, payments. Just want an honest conversation before I commit to recruiting there.', ARRAY['crypto', 'career', 'industry switch']::text[], (select id from public.users where email = 'priya.bansal@cohort.edu'), 'open', '2026-08-25T00:00:00.000Z'),
  ('Anyone cracked an LBO model in under 45 minutes?', 'I can build it, just not at interview speed. Looking for someone who has done a timed modelling test to watch me do one and tell me where I''m slow.', ARRAY['LBO', 'modelling', 'private equity']::text[], (select id from public.users where email = 'nikhil.joshi@cohort.edu'), 'open', '2026-08-21T00:00:00.000Z'),
  ('Looking for a mock interviewer for MBB final rounds', 'Two final rounds in three weeks. I need someone who will actually be harsh about structure rather than nice about it.', ARRAY['consulting', 'mock interview', 'MBB']::text[], (select id from public.users where email = 'tara.menon@cohort.edu'), 'open', '2026-08-24T00:00:00.000Z'),
  ('Need someone to explain options pricing like I''m five', 'Derivatives elective is losing me at Black-Scholes. Happy to trade for CV review or consulting case practice.', ARRAY['derivatives', 'academics', 'finance']::text[], (select id from public.users where email = 'aditya.verma@cohort.edu'), 'open', '2026-08-25T00:00:00.000Z');
